(function(){"use strict";var R=document.documentElement,raf=0;function on(){return R.getAttribute("data-visual")==="novo"}function fonte(){if(!on()||document.getElementById("cz-font"))return;var l=document.createElement("link");l.id="cz-font";l.rel="stylesheet";l.href="https://fonts.googleapis.com/css2?family=Rajdhani:wght@600;700&display=swap";(document.head||R).appendChild(l)}function spot(e){if(!on()||!e.target||!e.target.closest)return;var t=e.target.closest('.mod-card,.panel,div[style*="flex: 0 0 250px"]');if(!t)return;var r=t.getBoundingClientRect();t.style.setProperty("--mx",Math.round(e.clientX-r.left)+"px");t.style.setProperty("--my",Math.round(e.clientY-r.top)+"px")}function wire(){raf=0;if(!on())return;var a=document.querySelector(".nav-item.active"),sb=document.querySelector(".sidebar"),ct=document.querySelector(".content");var side="-999px",main="-999px";if(a&&sb&&ct){var ra=a.getBoundingClientRect(),rs=sb.getBoundingClientRect(),rc=ct.getBoundingClientRect();var y=ra.top+ra.height/2;if(y>rs.top+6&&y<rs.bottom-6&&y>rc.top&&y<rc.bottom&&ra.width>0){side=Math.round(y-rs.top)+"px";main=Math.round(y-rc.top)+"px"}}R.style.setProperty("--cz-ay-side",side);R.style.setProperty("--cz-ay-main",main)}function ask(){if(!raf)raf=requestAnimationFrame(wire)}function start(){fonte();document.addEventListener("pointermove",spot,{passive:true});window.addEventListener("scroll",ask,{passive:true,capture:true});window.addEventListener("resize",ask,{passive:true});if(window.MutationObserver&&document.body){new MutationObserver(ask).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["class","data-visual"]})}ask()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start);else start()})();